import { ImageResponse } from "@vercel/og";
import { redis, KEY } from "@/lib/redis";

export const runtime = "edge";

interface Reminder {
  id: string;
  text: string;
  done: boolean;
  order: number;
}

// ── Canvas ────────────────────────────────────────────────────────────────────
const W = 1179;
const H = 2556;

// ── Palette ───────────────────────────────────────────────────────────────────
const ORANGE = "#FF693C";
const WHITE  = "#FFFFFF";
const DONE_C = "#484848";

// ── Safe zone ─────────────────────────────────────────────────────────────────
// iPhone 14 Pro clock ends around y≈730. 780 gives a comfortable clearance.
const SAFE_TOP    = 780;
const SAFE_BOTTOM = 2280;

// ── Layout ───────────────────────────────────────────────────────────────────
const SIDE_PAD = 68;
const BAR_W    = 4;
const BAR_MR   = 18;
const NUM_W    = 60;
const COL_GAP  = 20;
// Width available for reminder text
const TEXT_W   = W - 2 * SIDE_PAD - BAR_W - BAR_MR - NUM_W - COL_GAP; // 941 px

const HEADER_H  = 86;   // REMINDERS header + divider
const FOOTER_H  = 215;  // signature + timestamp strip (tall enough for sig)

const FONT_MAX   = 118;
const FONT_MIN   = 34;
// Conservative avg char-width / fontSize for Inter Bold
const CHAR_RATIO = 0.62;
// Row-height multipliers
const RATIO_1LN  = 1.40;   // single-line item: H = fontSize × RATIO_1LN
const RATIO_2LN  = 2.70;   // two-line  item:  H = fontSize × RATIO_2LN

// ── Assets ────────────────────────────────────────────────────────────────────
const FONT_B64 = "";
const SIGN_B64 = "";

function b64ToBuffer(b64: string): ArrayBuffer {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out.buffer;
}
const fontData = b64ToBuffer(FONT_B64);

// ── Font-size algorithm with wrapping support ─────────────────────────────────
// Finds the largest font size at which all reminder rows fit vertically,
// allowing long texts to wrap onto a second line (capped at 2 lines).
function computeLayout(
  items: { text: string }[],
  textW: number,
  availH: number,
): { fontSize: number; itemHeights: number[] } {
  const N = items.length;
  if (N === 0) return { fontSize: FONT_MAX, itemHeights: [] };

  for (let F = FONT_MAX; F >= FONT_MIN; F -= 2) {
    const charsPerLine = Math.max(1, Math.floor(textW / (F * CHAR_RATIO)));
    const heights = items.map(({ text }) => {
      const lines = Math.min(2, Math.max(1, Math.ceil(text.length / charsPerLine)));
      return Math.round(F * (lines === 1 ? RATIO_1LN : RATIO_2LN));
    });
    if (heights.reduce((a, b) => a + b, 0) <= availH) {
      return { fontSize: F, itemHeights: heights };
    }
  }

  // Fallback at minimum font size
  const charsPerLine = Math.max(1, Math.floor(textW / (FONT_MIN * CHAR_RATIO)));
  return {
    fontSize: FONT_MIN,
    itemHeights: items.map(({ text }) => {
      const lines = Math.min(2, Math.max(1, Math.ceil(text.length / charsPerLine)));
      return Math.round(FONT_MIN * (lines === 1 ? RATIO_1LN : RATIO_2LN));
    }),
  };
}

// ── Route ─────────────────────────────────────────────────────────────────────
export async function GET() {
  const data   = await redis.get<Reminder[]>(KEY);
  const all    = (data ?? []).sort((a, b) => a.order - b.order);

  const sorted  = [...all.filter(r => !r.done), ...all.filter(r => r.done)];
  const pending = sorted.filter(r => !r.done);
  const N       = sorted.length;

  const availH = SAFE_BOTTOM - SAFE_TOP - HEADER_H - FOOTER_H;
  const { fontSize, itemHeights } = computeLayout(sorted, TEXT_W, availH);

  const NUM_PX  = Math.max(22, Math.round(fontSize * 0.35));
  const totalItemH = itemHeights.reduce((a, b) => a + b, 0);
  const blockH  = HEADER_H + totalItemH + FOOTER_H;

  // Centre block around screen midpoint; never go above SAFE_TOP
  const topPad = Math.max(
    SAFE_TOP,
    Math.min(Math.floor(H / 2 - blockH / 2), SAFE_BOTTOM - blockH),
  );

  const timeStr = new Date().toLocaleTimeString("en-US", {
    hour: "2-digit", minute: "2-digit",
  });

  // Letter-spacing: tighter at large sizes for premium feel
  const textLS = fontSize > 72 ? "-0.04em" : fontSize > 50 ? "-0.02em" : "-0.01em";

  // Signature: display at 280 px wide, preserve 624×400 aspect ratio → 180 px tall
  const SIGN_W = 280;
  const SIGN_H = Math.round(SIGN_W * (400 / 624)); // ≈ 180

  return new ImageResponse(
    (
      <div style={{
        width: W, height: H, background: "#000",
        display: "flex", fontFamily: "Inter", position: "relative",
      }}>

        {/* Depth gradient */}
        <div style={{
          position: "absolute", top: 0, left: 0, right: 0, bottom: 0, display: "flex",
          background: "linear-gradient(180deg,#000 0%,#060606 45%,#030303 70%,#000 100%)",
        }} />

        {/* Content column */}
        <div style={{
          display: "flex", flexDirection: "column",
          paddingTop: topPad, paddingLeft: SIDE_PAD, paddingRight: SIDE_PAD,
          width: "100%", position: "relative",
        }}>

          {/* ── Header ── */}
          <div style={{
            display: "flex", alignItems: "center",
            justifyContent: "space-between", height: 50, marginBottom: 12,
          }}>
            <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
              <div style={{
                width: 7, height: 7, background: ORANGE,
                borderRadius: "50%", display: "flex", flexShrink: 0,
              }} />
              <span style={{ fontSize: 26, color: ORANGE, letterSpacing: "0.40em", fontWeight: 700 }}>
                REMINDERS
              </span>
            </div>
            <span style={{
              fontSize: 26,
              color: pending.length > 0 ? ORANGE : "#2e2e2e",
              letterSpacing: "0.08em", fontWeight: 700,
            }}>
              {pending.length > 0 ? `${pending.length} left` : N > 0 ? "all done  ✓" : ""}
            </span>
          </div>

          {/* ── Divider ── */}
          <div style={{ height: 1, background: ORANGE, opacity: 0.2, marginBottom: 22, display: "flex" }} />

          {/* ── Empty state ── */}
          {N === 0 && (
            <div style={{ display: "flex", alignItems: "center", height: 200 }}>
              <span style={{ fontSize: 96, color: ORANGE, fontWeight: 700, letterSpacing: "-0.04em" }}>
                all set.
              </span>
            </div>
          )}

          {/* ── Reminder rows ── */}
          {sorted.map((r, i) => (
            <div key={r.id} style={{
              display: "flex",
              alignItems: "center",
              height: itemHeights[i],
              borderBottom: i < N - 1 ? "1px solid #0A0A0A" : "none",
            }}>
              {/* Left accent bar */}
              <div style={{
                width: BAR_W,
                height: Math.round(itemHeights[i] * 0.45),
                background: r.done ? "transparent" : ORANGE,
                borderRadius: 2, flexShrink: 0, marginRight: BAR_MR,
              }} />

              {/* Number */}
              <span style={{
                fontSize: NUM_PX, color: ORANGE, fontWeight: 700,
                letterSpacing: "0.06em", width: NUM_W, textAlign: "right",
                flexShrink: 0, opacity: r.done ? 0.40 : 1, lineHeight: 1,
              }}>
                {String(i + 1).padStart(2, "0")}
              </span>

              {/* Spacer */}
              <div style={{ width: COL_GAP, flexShrink: 0 }} />

              {/* Text — flex:1 lets Satori word-wrap naturally, no overflow clipping */}
              <span style={{
                fontSize, color: r.done ? DONE_C : WHITE, fontWeight: 700,
                letterSpacing: textLS,
                textDecoration: r.done ? "line-through" : "none",
                flex: 1, lineHeight: 1.15,
              }}>
                {r.text}
              </span>
            </div>
          ))}

          {/* ── Footer: timestamp + signature ── */}
          <div style={{
            display: "flex", justifyContent: "space-between", alignItems: "flex-end",
            marginTop: 20, height: FOOTER_H - 20,
          }}>
            <span style={{ fontSize: 17, color: "#1c1c1c", letterSpacing: "0.08em" }}>
              {timeStr}
            </span>
            {/* Full-resolution source (624×400) displayed at 280×180 — sharp at wallpaper DPI */}
            <img
              src={`data:image/png;base64,${SIGN_B64}`}
              style={{ width: SIGN_W, height: SIGN_H, opacity: 0.92 }}
            />
          </div>

        </div>
      </div>
    ),
    {
      width:  W,
      height: H,
      fonts: [{ name: "Inter", data: fontData, style: "normal", weight: 700 }],
    },
  );
}
